#!/bin/bash
S=/foss/pdks/sky130A/libs.tech/netgen/sky130A_setup.tcl
netgen -batch lvs "bitcell.spice bitcell" "schem.sp bitcell" $S lvs_bitcell.out > /dev/null 2>&1; r=$(grep -cE "Circuits match uniquely" lvs_bitcell.out); p=$(grep -c "Property errors were found" lvs_bitcell.out); [ "$p" != 0 ] && r=0; echo "LVS bitcell match_lines=$r $(grep -E "Property errors|Netlists do not match|Top level cell failed" lvs_bitcell.out | head -2 | tr "\n" " ")"
